-- Bachelor party site: one-off database set-up. Generated by scripts/build-setup-sql.mjs: do not edit.
-- Paste the whole file into the Supabase SQL editor and run it once, on an empty project.
-- It runs as one transaction: if anything fails, nothing is changed.

begin;

-- ===== migrations/20261116000000_schema.sql =====
-- Bachelor party site: schema (stage a)
-- Spec: docs/requirements.md section 4.
-- Money: integer USD cents, plus the currency the figure was quoted in.
-- GBP is never stored as a total; it is derived from fx_rates at display time.

-- ---------------------------------------------------------------------------
-- Core tables (section 4)
-- ---------------------------------------------------------------------------

create table cities (
  id   text primary key,
  name text not null unique
);

-- Pages the research took figures from.
create table sources (
  id           bigint generated by default as identity primary key,
  slug         text not null unique,
  title        text not null,
  url          text,                      -- null for a person (e.g. the organiser)
  date_checked date not null,
  publisher    text,
  notes        text
);

-- One row per hotel, activity, transfer, flight or payment tool.
create table options (
  id                   bigint generated by default as identity primary key,
  slug                 text not null unique,
  city_id              text references cities (id),   -- null: not city-specific, or city TBC
  category             text not null check (category in ('stay', 'activity', 'food', 'transport', 'payment')),
  name                 text not null,
  tier                 text check (tier in ('budget', 'mid', 'premium')),
  price_amount         integer check (price_amount >= 0),       -- USD cents; null: price not known
  price_amount_high    integer check (price_amount_high >= 0),  -- USD cents; top of a quoted range
  price_unit           text not null check (price_unit in ('per_person', 'per_room_night', 'flat')),
  currency             text not null default 'USD' check (currency in ('USD', 'GBP')),  -- currency quoted in
  quoted_amount        integer check (quoted_amount >= 0),      -- minor units of `currency`, when not USD
  quoted_amount_high   integer check (quoted_amount_high >= 0),
  price_note           text,
  lead_time_days       integer check (lead_time_days >= 0),
  lead_time_note       text,
  status               text not null default 'shortlist' check (status in ('shortlist', 'chosen', 'rejected')),
  groom_fit_note       text,
  notes                text,
  verified             boolean not null default false,          -- unverified is the default
  model_input          boolean not null default false,          -- the row the cost calculator reads
  excluded_from_totals boolean not null default false,          -- flights: shown, never summed
  created_at           timestamptz not null default now(),
  check (price_amount_high is null or price_amount is not null),
  check (currency = 'USD' or price_amount is null or quoted_amount is not null),
  check (not model_input or (price_amount is not null and tier is not null and city_id is not null)),
  check (not (model_input and excluded_from_totals))
);

-- The calculator needs exactly one stay rate and one transfer fare per city and tier.
create unique index options_one_model_input on options (city_id, category, tier) where model_input;

-- Saved calculator runs.
create table scenarios (
  id            bigint generated by default as identity primary key,
  name          text not null,
  city_id       text not null references cities (id),
  tier          text not null check (tier in ('budget', 'mid', 'premium')),
  nights        integer not null check (nights in (2, 3)),
  group_size    integer not null check (group_size > 0),
  local_guests  integer not null default 0 check (local_guests >= 0),
  groom_covered boolean not null default true,
  created_at    timestamptz not null default now(),
  check (local_guests < group_size)
);

-- Assumptions register (FR-11). `value` holds numbers; `value_text` holds facts
-- that are not numbers (dates, headcount range). Money values are USD cents.
create table assumptions (
  id          bigint generated by default as identity primary key,
  key         text not null,
  city_id     text references cities (id),   -- null: applies to both cities
  value       numeric,
  value_text  text,
  unit        text not null check (unit in ('percent', 'usd_cents', 'beds', 'legs', 'flag', 'text')),
  currency    text check (currency in ('USD', 'GBP')),  -- currency quoted in, for money values
  reason      text,
  status_note text,                           -- e.g. "Confirmed by Jack", "Sources conflict"
  verified    boolean not null default false,
  created_at  timestamptz not null default now(),
  check (value is not null or value_text is not null),
  check (unit <> 'usd_cents' or (value = trunc(value) and currency is not null)),
  unique nulls not distinct (key, city_id)
);

-- Latest row wins; history is kept.
create table fx_rates (
  id         bigint generated by default as identity primary key,
  from_ccy   text not null check (from_ccy in ('USD', 'GBP')),
  to_ccy     text not null check (to_ccy in ('USD', 'GBP')),
  rate       numeric(12, 6) not null check (rate > 0),
  as_of      date not null,
  source_id  bigint references sources (id),
  note       text,
  created_at timestamptz not null default now(),
  check (from_ccy <> to_ccy)
);

-- Links any option, assumption or FX rate to the source it came from.
create table source_links (
  id              bigint generated by default as identity primary key,
  source_id       bigint not null references sources (id),
  entity_type     text not null check (entity_type in ('option', 'assumption', 'fx_rate', 'decision', 'open_question')),
  entity_id       bigint not null,
  quote_or_figure text,
  unique (source_id, entity_type, entity_id)
);

-- Where sources disagree, or the only source is weak. Both values are kept.
create table conflicts (
  id          bigint generated by default as identity primary key,
  entity_type text not null check (entity_type in ('option', 'assumption', 'fx_rate')),
  entity_id   bigint not null,
  title       text not null,
  source_a    bigint references sources (id),   -- null: page not recorded in research
  source_b    bigint references sources (id),
  value_a     text not null,
  value_b     text,
  used        text not null,
  why         text not null
);

-- Append-only: rows cannot be deleted, only superseded. Edits are audited.
create table decisions (
  id                bigint generated by default as identity primary key,
  date              date not null,
  title             text not null,
  decision          text not null,
  reason            text,
  decided_by        text not null,
  linked_option_ids bigint[] not null default '{}',
  superseded_by     bigint references decisions (id),
  created_at        timestamptz not null default now()
);

create table open_questions (
  id                    bigint generated by default as identity primary key,
  question              text not null,
  owner                 text not null,
  status                text not null default 'open' check (status in ('open', 'answered')),
  answer                text,
  closed_by_decision_id bigint references decisions (id),
  created_at            timestamptz not null default now(),
  -- Closing a question requires the decision that answers it.
  constraint answered_needs_decision check (status = 'open' or closed_by_decision_id is not null)
);

-- ---------------------------------------------------------------------------
-- Supporting tables (section 4)
-- Privacy: name and currency only. No contact, card or bank details anywhere.
-- ---------------------------------------------------------------------------

create table guests (
  id           bigint generated by default as identity primary key,
  name         text not null,
  home_country text,
  bed_needed   boolean not null default true,
  role         text not null default 'group' check (role in ('organiser', 'group', 'groom')),
  currency     text not null check (currency in ('USD', 'GBP'))
);

-- Records only. No payment processing.
create table payments (
  id            bigint generated by default as identity primary key,
  guest_id      bigint not null references guests (id),
  amount        integer not null check (amount >= 0),   -- USD cents
  currency      text not null check (currency in ('USD', 'GBP')),  -- currency the guest is quoted in
  quoted_amount integer check (quoted_amount >= 0),     -- minor units of `currency`, when not USD
  due_date      date,
  paid_date     date
);

create table votes (
  id        bigint generated by default as identity primary key,
  option_id bigint not null references options (id),
  guest_id  bigint not null references guests (id),
  vote      smallint not null check (vote in (-1, 1)),
  unique (option_id, guest_id)
);

create table comments (
  id          bigint generated by default as identity primary key,
  entity_type text not null check (entity_type in ('option', 'decision', 'open_question')),
  entity_id   bigint not null,
  guest_id    bigint not null references guests (id),
  body        text not null,
  created_at  timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Additions to section 4
-- ---------------------------------------------------------------------------

-- Site switches, e.g. whether the groom view is published.
create table app_settings (
  key        text primary key,
  value      text not null,
  updated_at timestamptz not null default now()
);

-- Audit trail (section 6): who, when and the old value.
create table audit_log (
  id         bigint generated by default as identity primary key,
  table_name text not null,
  row_id     text not null,
  action     text not null check (action in ('insert', 'update', 'delete')),
  actor      text not null,
  at         timestamptz not null default now(),
  old_row    jsonb,
  new_row    jsonb
);

-- The app sets `app.actor` for the transaction; otherwise the actor is "system".
create function audit_row() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  who text := coalesce(nullif(current_setting('app.actor', true), ''), 'system');
begin
  if tg_op = 'INSERT' then
    insert into audit_log (table_name, row_id, action, actor, new_row)
    values (tg_table_name, to_jsonb(new) ->> coalesce(tg_argv[0], 'id'), 'insert', who, to_jsonb(new));
    return new;
  elsif tg_op = 'UPDATE' then
    if to_jsonb(old) is distinct from to_jsonb(new) then
      insert into audit_log (table_name, row_id, action, actor, old_row, new_row)
      values (tg_table_name, to_jsonb(old) ->> coalesce(tg_argv[0], 'id'), 'update', who, to_jsonb(old), to_jsonb(new));
    end if;
    return new;
  else
    insert into audit_log (table_name, row_id, action, actor, old_row)
    values (tg_table_name, to_jsonb(old) ->> coalesce(tg_argv[0], 'id'), 'delete', who, to_jsonb(old));
    return old;
  end if;
end $$;

create trigger audit_options        after insert or update or delete on options        for each row execute function audit_row();
create trigger audit_assumptions    after insert or update or delete on assumptions    for each row execute function audit_row();
create trigger audit_fx_rates       after insert or update or delete on fx_rates       for each row execute function audit_row();
create trigger audit_scenarios      after insert or update or delete on scenarios      for each row execute function audit_row();
create trigger audit_decisions      after insert or update or delete on decisions      for each row execute function audit_row();
create trigger audit_open_questions after insert or update or delete on open_questions for each row execute function audit_row();
create trigger audit_app_settings   after insert or update or delete on app_settings   for each row execute function audit_row('key');

-- Decisions and the audit trail cannot be deleted; the audit trail cannot be edited.
create function forbid_change() returns trigger
language plpgsql as $$
begin
  raise exception '% rows cannot be %', tg_table_name, case tg_op when 'DELETE' then 'deleted' else 'changed' end;
end $$;

create trigger decisions_no_delete before delete on decisions for each row execute function forbid_change();
create trigger audit_log_immutable before update or delete on audit_log for each row execute function forbid_change();

-- ---------------------------------------------------------------------------
-- Private by default: row-level security on, no policies. Nothing is readable
-- with the public key until stage (e) adds passcode-checked access.
-- ---------------------------------------------------------------------------

alter table cities         enable row level security;
alter table sources        enable row level security;
alter table options        enable row level security;
alter table scenarios      enable row level security;
alter table assumptions    enable row level security;
alter table fx_rates       enable row level security;
alter table source_links   enable row level security;
alter table conflicts      enable row level security;
alter table decisions      enable row level security;
alter table open_questions enable row level security;
alter table guests         enable row level security;
alter table payments       enable row level security;
alter table votes          enable row level security;
alter table comments       enable row level security;
alter table app_settings   enable row level security;
alter table audit_log      enable row level security;

-- ===== migrations/20261116000100_access.sql =====
-- Access by passcode link (stage b reads; stage e relies on the role rules).
-- Three passcodes, one per role. Only a hash of each is stored.
-- Tables stay locked by row-level security; the site reads everything through
-- api_bundle(), which checks the passcode and returns only what that role may see.

create table access_codes (
  role       text primary key check (role in ('organiser', 'group', 'groom')),
  code_hash  text not null unique,
  updated_at timestamptz not null default now()
);
alter table access_codes enable row level security;

create function hash_code(p_code text) returns text
language sql immutable as $$
  select encode(sha256(convert_to(coalesce(p_code, ''), 'UTF8')), 'hex')
$$;

-- Run by the site owner in the SQL editor, never from the website.
create function set_access_code(p_role text, p_code text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if length(coalesce(p_code, '')) < 16 then
    raise exception 'A passcode needs at least 16 characters';
  end if;
  insert into access_codes (role, code_hash) values (p_role, hash_code(p_code))
  on conflict (role) do update set code_hash = excluded.code_hash, updated_at = now();
end $$;

revoke all on function set_access_code(text, text) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function set_access_code(text, text) from anon, authenticated;
  end if;
end $$;

create function api_role(p_code text) returns text
language sql stable security definer set search_path = public as $$
  select role from access_codes where code_hash = hash_code(p_code)
$$;

-- One data load for the whole site.
--   groom, before publish: nothing but his role.
--   groom, after publish:  what the Verdict and Workings pages need.
--   group:                 plus options detail, decisions, questions, votes, comments.
--   organiser:             plus payments and the audit trail.
create function api_bundle(p_code text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  r   text := api_role(p_code);
  pub boolean;
  b   jsonb;
begin
  if r is null then
    raise exception 'That passcode is not recognised' using errcode = '28000';
  end if;

  select value = 'true' into pub from app_settings where key = 'groom_view_published';
  pub := coalesce(pub, false);

  if r = 'groom' and not pub then
    return jsonb_build_object('role', r, 'published', false);
  end if;

  b := jsonb_build_object(
    'role', r,
    'published', pub,
    'settings',     (select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) from app_settings),
    'cities',       (select coalesce(jsonb_agg(to_jsonb(t) order by t.id), '[]'::jsonb) from cities t),
    'options',      (select coalesce(jsonb_agg(to_jsonb(t) order by t.id), '[]'::jsonb) from options t
                      where r <> 'groom' or t.category <> 'payment'),
    'assumptions',  (select coalesce(jsonb_agg(to_jsonb(t) order by t.id), '[]'::jsonb) from assumptions t),
    'fx_rates',     (select coalesce(jsonb_agg(to_jsonb(t) order by t.as_of desc, t.id desc), '[]'::jsonb) from fx_rates t),
    'sources',      (select coalesce(jsonb_agg(to_jsonb(t) order by t.id), '[]'::jsonb) from sources t),
    'source_links', (select coalesce(jsonb_agg(to_jsonb(t) order by t.id), '[]'::jsonb) from source_links t
                      where t.entity_type in ('option', 'assumption', 'fx_rate')),
    'conflicts',    (select coalesce(jsonb_agg(to_jsonb(t) order by t.id), '[]'::jsonb) from conflicts t),
    'scenarios',    (select coalesce(jsonb_agg(to_jsonb(t) order by t.id), '[]'::jsonb) from scenarios t)
  );

  if r in ('organiser', 'group') then
    b := b || jsonb_build_object(
      'decisions',      (select coalesce(jsonb_agg(to_jsonb(t) order by t.date desc, t.id desc), '[]'::jsonb) from decisions t),
      'open_questions', (select coalesce(jsonb_agg(to_jsonb(t) order by t.id), '[]'::jsonb) from open_questions t),
      'guests',         (select coalesce(jsonb_agg(to_jsonb(t) order by t.id), '[]'::jsonb) from guests t),
      'votes',          (select coalesce(jsonb_agg(to_jsonb(t) order by t.id), '[]'::jsonb) from votes t),
      'comments',       (select coalesce(jsonb_agg(to_jsonb(t) order by t.id), '[]'::jsonb) from comments t),
      'decision_history', (select coalesce(jsonb_agg(to_jsonb(t) order by t.id), '[]'::jsonb) from audit_log t
                            where t.table_name = 'decisions')
    );
  end if;

  if r = 'organiser' then
    b := b || jsonb_build_object(
      'payments',  (select coalesce(jsonb_agg(to_jsonb(t) order by t.id), '[]'::jsonb) from payments t),
      'audit_log', (select coalesce(jsonb_agg(to_jsonb(t) order by t.id desc), '[]'::jsonb)
                      from (select * from audit_log where actor <> 'seed' order by id desc limit 300) t)
    );
  end if;

  return b;
end $$;

-- ===== migrations/20261116000200_writes.sql =====
-- Writes (stages d and e). Every change goes through one of these functions,
-- which check the passcode's role first. Tables stay locked to direct access.
--   organiser: edit inputs, options, decisions, questions, guests, payments, settings
--   group:     vote and comment
--   groom:     nothing

-- Checks the passcode, sets who is acting (for the audit trail), returns the role.
create function require_role(p_code text, variadic p_roles text[]) returns text
language plpgsql security definer set search_path = public as $$
declare
  r text := api_role(p_code);
begin
  if r is null then
    raise exception 'That passcode is not recognised' using errcode = '28000';
  end if;
  if not (r = any (p_roles)) then
    raise exception 'You do not have permission to do that' using errcode = '42501';
  end if;
  if r = 'organiser' then
    perform set_config('app.actor', coalesce((select name from guests where role = 'organiser' order by id limit 1), 'Organiser'), true);
  end if;
  return r;
end $$;

-- Add (no id) or change (with id) one row. Organiser only.
create function api_upsert(p_code text, p_table text, p_row jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_id   bigint := nullif(p_row ->> 'id', '')::bigint;
  v_row  jsonb := p_row;
  cols   text;
  vals   text;
  result jsonb;
begin
  perform require_role(p_code, 'organiser');

  if not (p_table = any (array['options', 'assumptions', 'fx_rates', 'scenarios', 'decisions', 'open_questions', 'guests', 'payments', 'conflicts'])) then
    raise exception 'That cannot be edited here';
  end if;
  if p_table = 'fx_rates' and v_id is not null then
    raise exception 'Exchange rates are kept as history. Add a new rate instead.';
  end if;
  if p_table = 'options' and v_id is null and not (v_row ? 'slug') then
    v_row := v_row || jsonb_build_object('slug', 'opt-' || substr(md5(random()::text || clock_timestamp()::text), 1, 10));
  end if;

  -- No figure is "verified" without a source.
  if p_table in ('options', 'assumptions') and coalesce((v_row ->> 'verified')::boolean, false) then
    if v_id is null or not exists (
      select 1 from source_links l
      where l.entity_id = v_id and l.entity_type = case p_table when 'options' then 'option' else 'assumption' end
    ) then
      raise exception 'Add a source before marking this verified';
    end if;
  end if;

  select string_agg(quote_ident(c.column_name), ', '), string_agg('r.' || quote_ident(c.column_name), ', ')
    into cols, vals
  from information_schema.columns c
  where c.table_schema = 'public' and c.table_name = p_table
    and v_row ? c.column_name and c.column_name not in ('id', 'created_at');
  if cols is null then
    raise exception 'Nothing to save';
  end if;

  if v_id is null then
    execute format('insert into %I (%s) select %s from jsonb_populate_record(null::%I, $1) r returning to_jsonb(%I.*)',
                   p_table, cols, vals, p_table, p_table)
      using v_row into result;
  else
    execute format('update %I t set (%s) = row(%s) from jsonb_populate_record(null::%I, $1) r where t.id = $2 returning to_jsonb(t.*)',
                   p_table, cols, vals, p_table)
      using v_row, v_id into result;
    if result is null then
      raise exception 'That row no longer exists';
    end if;
  end if;
  return result;
end $$;

-- Remove a row. Never decisions, options, assumptions or exchange rates.
create function api_delete(p_code text, p_table text, p_id bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  perform require_role(p_code, 'organiser');
  if not (p_table = any (array['scenarios', 'payments', 'source_links', 'conflicts'])) then
    raise exception 'That cannot be deleted';
  end if;
  execute format('delete from %I where id = $1', p_table) using p_id;
  return jsonb_build_object('deleted', p_id);
end $$;

-- Replace a decision: the old one stays in the log, marked as superseded.
create function api_supersede_decision(p_code text, p_old_id bigint, p_row jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  new_row jsonb;
begin
  perform require_role(p_code, 'organiser');
  if not exists (select 1 from decisions where id = p_old_id and superseded_by is null) then
    raise exception 'That decision has already been superseded, or does not exist';
  end if;
  new_row := api_upsert(p_code, 'decisions', p_row - 'id' - 'superseded_by');
  update decisions set superseded_by = (new_row ->> 'id')::bigint where id = p_old_id;
  return new_row;
end $$;

-- Attach a source (a page actually opened, with the date) to an option or assumption.
create function api_add_source(
  p_code text, p_entity_type text, p_entity_id bigint,
  p_title text, p_url text, p_date_checked date, p_publisher text, p_quote text
) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  sid bigint;
begin
  perform require_role(p_code, 'organiser');
  if p_entity_type not in ('option', 'assumption') then
    raise exception 'Sources attach to options and assumptions';
  end if;
  if coalesce(trim(p_title), '') = '' or p_date_checked is null then
    raise exception 'A source needs a title and the date it was checked';
  end if;
  if p_url is not null and p_url !~* '^https?://' then
    raise exception 'The link must start with http:// or https://';
  end if;
  insert into sources (slug, title, url, date_checked, publisher)
  values ('src-' || substr(md5(random()::text || clock_timestamp()::text), 1, 10), trim(p_title), nullif(trim(p_url), ''), p_date_checked, nullif(trim(p_publisher), ''))
  returning id into sid;
  insert into source_links (source_id, entity_type, entity_id, quote_or_figure)
  values (sid, p_entity_type, p_entity_id, nullif(trim(p_quote), ''));
  return jsonb_build_object('source_id', sid);
end $$;

-- Site switches: publish the groom view, mark the verdict final, stale-data age.
create function api_set_setting(p_code text, p_key text, p_value text) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  perform require_role(p_code, 'organiser');
  if not (p_key = any (array['groom_view_published', 'verdict_status', 'stale_after_days', 'payment_buffer_pct'])) then
    raise exception 'Unknown setting';
  end if;
  if p_key = 'groom_view_published' and p_value not in ('true', 'false') then raise exception 'Use true or false'; end if;
  if p_key = 'verdict_status' and p_value not in ('provisional', 'final') then raise exception 'Use provisional or final'; end if;
  insert into app_settings (key, value) values (p_key, p_value)
  on conflict (key) do update set value = excluded.value, updated_at = now();
  return jsonb_build_object('key', p_key, 'value', p_value);
end $$;

-- Guests act under the name they picked. The groom never votes or comments.
create function acting_guest(p_guest_id bigint) returns text
language plpgsql security definer set search_path = public as $$
declare
  n text;
begin
  select name into n from guests where id = p_guest_id and role <> 'groom';
  if n is null then
    raise exception 'Choose your name first';
  end if;
  perform set_config('app.actor', n, true);
  return n;
end $$;

-- p_vote: 1 for, -1 against, 0 to take the vote back.
create function api_vote(p_code text, p_guest_id bigint, p_option_id bigint, p_vote integer) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  perform require_role(p_code, 'organiser', 'group');
  perform acting_guest(p_guest_id);
  if p_vote = 0 then
    delete from votes where option_id = p_option_id and guest_id = p_guest_id;
  elsif p_vote in (1, -1) then
    insert into votes (option_id, guest_id, vote) values (p_option_id, p_guest_id, p_vote)
    on conflict (option_id, guest_id) do update set vote = excluded.vote;
  else
    raise exception 'A vote is for, against, or none';
  end if;
  return jsonb_build_object('option_id', p_option_id, 'vote', p_vote);
end $$;

create function api_comment(p_code text, p_guest_id bigint, p_entity_type text, p_entity_id bigint, p_body text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  cid bigint;
begin
  perform require_role(p_code, 'organiser', 'group');
  perform acting_guest(p_guest_id);
  if coalesce(trim(p_body), '') = '' then raise exception 'Write a comment first'; end if;
  if length(p_body) > 2000 then raise exception 'Keep comments under 2,000 characters'; end if;
  insert into comments (entity_type, entity_id, guest_id, body)
  values (p_entity_type, p_entity_id, p_guest_id, trim(p_body)) returning id into cid;
  return jsonb_build_object('id', cid);
end $$;

-- Guest and payment records are audited too: they are who-owes-what.
create trigger audit_guests   after insert or update or delete on guests   for each row execute function audit_row();
create trigger audit_payments after insert or update or delete on payments for each row execute function audit_row();

-- ===== migrations/20261116000300_harden.sql =====
-- Hardening after the Supabase security check.
-- Only the api_* functions are meant to be called from the website. Helper
-- functions are used inside them (they run as the owner), so nobody else needs
-- to call them directly.

alter function hash_code(text) set search_path = public;
alter function forbid_change() set search_path = public;

revoke all on function require_role(text, text[]) from public;
revoke all on function acting_guest(bigint) from public;
revoke all on function audit_row() from public;
revoke all on function forbid_change() from public;
revoke all on function hash_code(text) from public;
revoke all on function api_role(text) from public;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function require_role(text, text[]) from anon, authenticated;
    revoke all on function acting_guest(bigint) from anon, authenticated;
    revoke all on function audit_row() from anon, authenticated;
    revoke all on function forbid_change() from anon, authenticated;
    revoke all on function hash_code(text) from anon, authenticated;
    revoke all on function api_role(text) from anon, authenticated;
    -- Belt and braces: row-level security already hides every row.
    revoke all on all tables in schema public from anon, authenticated;
    revoke all on all sequences in schema public from anon, authenticated;
  end if;
end $$;

